import json, sys
def txt_content(c):
    parts=[]
    for item in (c or []):
        inner=item.get('content') if isinstance(item,dict) else None
        if isinstance(inner,dict): parts.append(inner.get('text',''))
        elif isinstance(item,dict) and 'text' in item: parts.append(item['text'])
        else: parts.append(str(item))
    return "\n".join(parts)
def render(msg):
    t=msg.get('type')
    if t=='user_message': return f"\n### USER\n{msg.get('text','')}"
    if t=='agent_thought': return f"\n[THOUGHT] {msg.get('text','')}"
    if t=='agent_message': return f"\n[AGENT] {msg.get('text','')}"
    if t=='tool_call':
        return f"\n>>> TOOL kind={msg.get('kind')} title={msg.get('title')}\n{txt_content(msg.get('content'))[:3000]}"
    if t=='tool_result':
        return f"\n<<< RESULT {txt_content(msg.get('content'))[:3000]}"
    return f"\n[{t}] {json.dumps(msg)[:800]}"
f=sys.argv[1]
d=json.load(open(f))
out=d['rollout'].get('output') or []
print("SCORE:", json.dumps(d['score'])[:2500]); print("="*60)
for m in out: print(render(m))
